// ❌ OLD: A Map holds keys STRONGLY. Every object inserted stays alive
// for as long as the Map exists — even when the rest of the app has
// dropped all references to it.
const metadata = new Map(); // ❌ OLD: strong key references

function cacheUser(user) {
  // The Map pins `user` and everything reachable from `expensiveMeta`.
  metadata.set(user, { lastSeen: Date.now(), sessions: 1000 });
}

function onUserGone(user) {
  // Even if the app no longer references `user`, the Map still does,
  // so it is NOT collectable → memory grows unboundedly.
  // (A manual metadata.delete(user) is easy to forget.)
}

// ✅ NEW: A WeakMap holds keys WEAKLY. When nothing else references
// `user`, both the key and the associated value become collectable —
// no manual cleanup required.
const metadata = new WeakMap(); // ✅ NEW: weak key — ephemeron entry

function cacheUser(user) {
  // The value is strongly held, but ONLY while the key is alive.
  metadata.set(user, { lastSeen: Date.now(), sessions: 1000 });
}

function onUserGone(user) {
  // Dropping the last strong reference to `user` makes the whole
  // entry unreachable; the GC reclaims key + value automatically.
  // No metadata.delete() call needed — this is the whole point.
}
